pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(address recipient) internal {
        recipient = address(this);
        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_run(address recipient) public {
        _run(recipient);
    }

    receive() external payable {
        revert("recipient rejects ETH");
    }
}
